public class Main {
    static int constructions = 0;

    static class Config {
        private Config() { constructions++; }
        // Holder idiom: Holder loads (and runs its initialiser) only on first use,
        // and the JVM guarantees class initialisation happens once, thread-safely.
        private static class Holder { static final Config INSTANCE = new Config(); }
        static Config getInstance() { return Holder.INSTANCE; }
    }

    public static void main(String[] args) {
        System.out.println("constructions before first use: " + constructions);
        Config a = Config.getInstance();
        Config b = Config.getInstance();
        System.out.println("same instance: " + (a == b));
        System.out.println("constructions: " + constructions);
    }
}

