public class Main {
    static class Registry {
        private static final Registry INSTANCE = new Registry();
        private static boolean created; // no "= false": it would run after INSTANCE is built
        private Registry() {
            // Guard: a second construction (e.g. by reflection) is refused.
            if (created) throw new IllegalStateException("already created");
            created = true;
        }
        static Registry get() { return INSTANCE; }
        // Like readResolve(): any "copy" request hands back the real instance.
        Registry copy() { return INSTANCE; }
        static Registry attack() { return new Registry(); }
    }

    public static void main(String[] args) {
        Registry r = Registry.get();
        try {
            Registry.attack();
            System.out.println("second instance created");
        } catch (IllegalStateException e) {
            System.out.println("second construction blocked: " + e.getMessage());
        }
        System.out.println("copy() returns same: " + (r.copy() == r));
    }
}

