public class Main {
    interface Shape { String name(); }
    static class Circle implements Shape { public String name() { return "Circle"; } }
    static class Square implements Shape { public String name() { return "Square"; } }

    // 1) Simple factory: one method, chosen by data.
    static Shape simple(String kind) { return kind.equals("circle") ? new Circle() : new Square(); }

    // 2) Factory method: the parent workflow calls an overridable create step.
    static abstract class Exporter {
        abstract String makeDoc();
        String export() { return "exported " + makeDoc(); }
    }
    static class PdfExporter extends Exporter { String makeDoc() { return "PDF"; } }

    // 3) Abstract factory: one object creates a whole matching family.
    interface ThemeFactory { String button(); String checkbox(); }
    static class DarkTheme implements ThemeFactory {
        public String button() { return "dark button"; }
        public String checkbox() { return "dark checkbox"; }
    }

    public static void main(String[] args) {
        System.out.println("simple: " + simple("circle").name());
        System.out.println("method: " + new PdfExporter().export());
        ThemeFactory t = new DarkTheme();
        System.out.println("abstract: " + t.button() + " + " + t.checkbox());
    }
}

