import java.util.*;
import java.util.function.*;

public class Main {
    interface Notification { String send(String to); }
    // Registry: key -> creator. Adding a product never edits create().
    static final Map<String, Supplier<Notification>> REG = new TreeMap<>();

    static void register(String key, Supplier<Notification> s) {
        if (REG.putIfAbsent(key, s) != null) throw new IllegalStateException("duplicate " + key);
    }
    static Notification create(String key) {
        Supplier<Notification> s = REG.get(key);
        if (s == null) throw new IllegalArgumentException("unknown '" + key + "'");
        return s.get();
    }

    public static void main(String[] args) {
        register("email", () -> to -> "Email to " + to);
        register("sms", () -> to -> "SMS to " + to);
        System.out.println("registered: " + REG.keySet());
        System.out.println("email: " + create("email").send("bob"));
        register("push", () -> to -> "Push to " + to); // new product, no edit to create()
        System.out.println("push: " + create("push").send("bob"));
        try { create("fax"); } catch (IllegalArgumentException e) { System.out.println("error: " + e.getMessage()); }
    }
}

