#include <bits/stdc++.h>
using namespace std;

using Notification = function<string(const string&)>;
map<string, function<Notification()>> REG;  // key -> creator (ordered by key)

void registerKind(const string& key, function<Notification()> c) {
    if (!REG.emplace(key, c).second) throw runtime_error("duplicate " + key);
}
Notification create(const string& key) {
    auto it = REG.find(key);
    if (it == REG.end()) throw invalid_argument("unknown '" + key + "'");
    return it->second();
}

int main() {
    registerKind("email", [] { return [](const string& to) { return "Email to " + to; }; });
    registerKind("sms", [] { return [](const string& to) { return "SMS to " + to; }; });
    string keys;
    for (auto& kv : REG) keys += (keys.empty() ? "" : ", ") + kv.first;
    cout << "registered: [" << keys << "]\n";
    cout << "email: " << create("email")("bob") << "\n";
    registerKind("push", [] { return [](const string& to) { return "Push to " + to; }; });
    cout << "push: " << create("push")("bob") << "\n";
    try { create("fax"); } catch (const invalid_argument& e) { cout << "error: " << e.what() << "\n"; }
