public class Main {
    interface Storage { String put(String k); }
    interface Queue { String push(String j); }
    // One factory = one whole family, so storage and queue always match.
    interface InfraFactory { Storage storage(); Queue queue(); }

    static class LocalFactory implements InfraFactory {
        public Storage storage() { return k -> "local-storage:" + k; }
        public Queue queue() { return j -> "local-queue:" + j; }
    }
    static class CloudFactory implements InfraFactory {
        public Storage storage() { return k -> "cloud-bucket:" + k; }
        public Queue queue() { return j -> "cloud-topic:" + j; }
    }
    // The client never names a concrete class.
    static void run(String label, InfraFactory f) {
        System.out.println(label + ": " + f.storage().put("a.txt") + " | " + f.queue().push("job1"));
    }

    public static void main(String[] args) {
        run("local", new LocalFactory());
        run("cloud", new CloudFactory());
    }
}

