    Order bad{&shared, {}};
    vector<string> own = {"a", "b"};
    Order good{nullptr, own};      // copy made here
    shared.push_back("c");         // builder reused later
    own.push_back("c");
    cout << "no copy: " << show(*bad.items) << "\n";
    cout << "copy: " << show(good.copy) << "\n";
}

