import java.util.*;

public class Main {
    static class Pool {
        private final int max; private int created = 0;
        private final Deque<String> idle = new ArrayDeque<>();
        private final Set<String> borrowed = new HashSet<>();
        Pool(int max) { this.max = max; }
        // Real pools block with a timeout; here we return null when exhausted.
        String borrow() {
            String c = idle.poll();
            if (c == null) {
                if (created == max) return null;
                c = "conn-" + (++created);
            }
            borrowed.add(c);
            return c;
        }
        // Only a connection we lent out may come back, and only once.
        boolean release(String c) {
            if (!borrowed.remove(c)) return false;
            idle.push(c);
            return true;
        }
    }

    public static void main(String[] args) {
        Pool p = new Pool(2);
        String a = p.borrow(), b = p.borrow();
        System.out.println("borrowed " + a);
        System.out.println("borrowed " + b);
        System.out.println("pool exhausted: " + (p.borrow() == null));
        System.out.println("released " + a + " -> " + p.release(a));
        System.out.println("double release -> " + p.release(a));
        System.out.println("reuse: " + p.borrow());
        System.out.println("created total: " + p.created);
    }
}

