import java.util.*;
import java.util.function.*;

public class Main {
    static int built = 0;
    static class Service { final int id = ++built; }

    // Mini container: a recipe per name, plus an optional cache for singleton scope.
    static class Container {
        Map<String, Supplier<Object>> recipes = new HashMap<>();
        Map<String, Object> cache = new HashMap<>();
        Set<String> singletons = new HashSet<>();
        void bean(String n, Supplier<Object> s, boolean singleton) {
            recipes.put(n, s);
            if (singleton) singletons.add(n);
        }
        Object get(String n) {
            if (!singletons.contains(n)) return recipes.get(n).get();   // prototype: new each time
            return cache.computeIfAbsent(n, k -> recipes.get(k).get()); // singleton: once
        }
    }

    public static void main(String[] args) {
        Container c = new Container();
        c.bean("single", Service::new, true);
        c.bean("proto", Service::new, false);
        System.out.println("singleton same: " + (c.get("single") == c.get("single")));
        System.out.println("prototype same: " + (c.get("proto") == c.get("proto")));
        System.out.println("instances built: " + built);
    }
}

