  constructor() { this.recipes = new Map(); this.cache = new Map(); this.singletons = new Set(); }
  bean(name, recipe, singleton) {
    this.recipes.set(name, recipe);
    if (singleton) this.singletons.add(name);
  }
  get(name) {
    if (!this.singletons.has(name)) return this.recipes.get(name)();   // prototype: new each time
    if (!this.cache.has(name)) this.cache.set(name, this.recipes.get(name)()); // singleton: once
    return this.cache.get(name);
  }
}

