#include <bits/stdc++.h>
using namespace std;

int built = 0;
struct Service { Service() { built++; } };

// Mini container: a recipe per name, plus an optional cache for singleton scope.
class Container {
    map<string, function<shared_ptr<Service>()>> recipes;
    map<string, shared_ptr<Service>> cache;
    set<string> singletons;
public:
    void bean(const string& n, function<shared_ptr<Service>()> r, bool singleton) {
        recipes[n] = r;
        if (singleton) singletons.insert(n);
    }
    shared_ptr<Service> get(const string& n) {
        if (!singletons.count(n)) return recipes[n]();            // prototype: new each time
        if (!cache.count(n)) cache[n] = recipes[n]();             // singleton: once
        return cache[n];
    }
};

