using System;
using System.Collections.Generic;

class Service { public static int Built = 0; public Service() { Built++; } }

// Mini container: a recipe per name, plus an optional cache for singleton scope.
class Container {
    Dictionary<string, Func<object>> recipes = new Dictionary<string, Func<object>>();
    Dictionary<string, object> cache = new Dictionary<string, object>();
    HashSet<string> singletons = new HashSet<string>();
    public void Bean(string n, Func<object> r, bool singleton) {
        recipes[n] = r;
        if (singleton) singletons.Add(n);
    }
    public object Get(string n) {
        if (!singletons.Contains(n)) return recipes[n]();                 // prototype: new each time
        if (!cache.ContainsKey(n)) cache[n] = recipes[n]();               // singleton: once
        return cache[n];
    }
}

